/**
 * AS-TC-011 — generated by the Automation Agent (cycle CYC-0001)
 * Test case:   TC-011 [negative/api] Inactive locationId LOC-SYN-004 is rejected
 * Requirement: REQ-005, REQ-013
 * Rule:        BR-003 A valid location is required.
 * Dataset:     DS-TC-011 (SYNTHETIC, seed TC-011:1.0.0)
 * Expected:    rejected with INVALID_LOCATION
 */
import { test, expect } from '../support/aqe';

test('TC-011 Inactive locationId LOC-SYN-004 is rejected', { tag: ["@BR-003","@REQ-005","@REQ-013","@negative","@api"] }, async ({ aqe }) => {
  const ds = aqe.dataset('DS-TC-011');
  const result = await aqe.createReservation(ds.values);
  expect(result.success, 'BR-003: createReservation.success').toBe(false);
  expect(result.reservation, 'BR-003: no reservation created').toBeNull();
  expect(result.errors.map((e) => e.code), 'BR-003: error codes').toContain('INVALID_LOCATION');
});
